const $=s=>document.querySelector(s), content=$('#content'), drawer=$('#drawer'), small=$('#small-dialog');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const navs=[['overview','◈','Overview'],['inventory','▤','Vehicle register'],['drivers','♙','Driver Register'],['review','◇','Review queue'],['sources','▦','Source comparison'],['activity','◷','Activity & backup']];
const sourceKeys=['fleet','emc','bancorp','moventum','balance','samsara'],sourceNames={fleet:'Fleet Sheet',emc:'EMC insurance',bancorp:'Bancorp',moventum:'Moventum',balance:'Balance sheet',samsara:'Samsara'};
let data,page='overview',search='',filter='all',stateFilter='',ownershipFilter='',driverFilter='',sectionFilter='',duplicateField='',duplicateValue='',sortKey='unitNumber',sortDirection='asc',index=0,selected=null,tab='profile',importData=null,pendingSource=null,driverSearch='',driverCheckFilter='',driverSortKey='name',driverSortDirection='asc';
const checks={identity:['Vehicle identity','VIN, plate, CCS number and vehicle description physically checked.'],location:['Current location','Actual city / state confirmed, not copied from an insurance address.'],ownership:['Ownership / lease','Title or lease documentation reviewed. Accounting alone is insufficient.'],registration:['Registration','Current registration and expiry checked.'],insurance:['Insurance','Current coverage and expiry confirmed against the policy.'],condition:['Physical condition','Tires, mechanical condition and deployability inspected.'],maintenance:['Maintenance baseline','Oil change, mileage and next-service requirements reviewed.'],equipment:['Equipment, fuel & toll','Required equipment, fuel card custody and toll tag checked.']};
const fmt=d=>d?new Date(d.length===10?d+'T12:00:00':d).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'Not recorded';
const badge=(s,t='')=>`<span class="badge ${t}">${esc(s)}</span>`;
const getV=id=>data.vehicles.find(v=>v.id===id);
const label=v=>v?.unitNumber?`CCS ${v.unitNumber}`:v?.vin?`VIN …${v.vin.slice(-6)}`:'Unresolved reference';
const evidence=v=>data.evidence.filter(e=>e.vehicleId===v.id);
const issues=v=>data.issues.filter(i=>i.vehicleId===v.id&&i.status==='Open');
const sourceState=(v,s)=>{const source=data.sources.find(x=>x.id===s);const es=evidence(v).filter(e=>e.sourceId===s&&(!source?.lastAcceptedUploadId||e.uploadId===source.lastAcceptedUploadId));if(!es.length)return'Not listed';if(es.some(e=>e.needsReview))return'Identifier conflict';if(s==='samsara'&&es.some(e=>['Exact VIN','Unique plate','Confirmed Samsara equipment'].includes(e.match)&&e.fields?.serial))return'Listed';if(es.some(e=>e.reportedVin&&e.reportedVin!==v.vin))return'VIN differs';return es.some(e=>e.match==='Exact VIN')?'Listed':es.some(e=>/suffix/i.test(e.match))?'Possible match':'Supporting only';};
const reviewStatus=v=>v.verificationStatus==='Verified'?badge('Verified','green'):issues(v).length?badge(`${issues(v).length} review item${issues(v).length===1?'':'s'}`,'amber'):badge(v.verificationStatus||'Not yet verified');

function ownershipInfo(v){
 const owner=String(v.ownership||'').toLowerCase();let key='unknown',label='Not confirmed';
 if(/lease/.test(owner)){
  if(/bancorp|bankorp/.test(owner)){key='bancorp';label='Leased · Bancorp';}
  else if(/union|moventum|momentum/.test(owner)){key='moventum';label='Leased · Moventum / Union';}
  else{key='lease';label='Leased · '+(v.ownership||'Provider needed');}
 }else if(/own/.test(owner)){key='owned';label='CCS owned';}
 else if(/loan|financ|chase/.test(owner)){key='financed';label='Financed · '+v.ownership;}
 else if(!owner){
  const providers=['bancorp','moventum'].filter(s=>sourceState(v,s)==='Listed');
  if(providers.length===1){key=providers[0];label='Leased · '+(key==='bancorp'?'Bancorp':'Moventum / Union')+' (source)';}
 }
 const accounting=sourceState(v,'balance');
 return {key,label,accounting:accounting!=='Not listed',tentative:accounting!=='Listed'};
}
function ownershipCell(v){const o=ownershipInfo(v);return `${badge(o.label,o.key==='unknown'?'':'blue')}${o.accounting?`<small>${badge(o.tentative?'Accounting asset · possible match':'Accounting asset','amber')}</small>`:''}`;}
function driverCell(v){return v.driver?`<div class="driver-cell"><span>${esc(v.driver)}</span><button class="driver-edit" data-driver="${v.id}" aria-label="Edit driver for ${esc(label(v))}" title="Edit driver">✎</button></div>`:`<button class="compact add-driver" data-driver="${v.id}">＋ Add driver</button>`;}
function driverModal(id){const v=getV(id);showSmall(v.driver?'Edit driver':'Add driver',`<p><b>${esc(label(v))}</b> · ${esc(v.plate||v.vin)}</p><form id="driver-form" data-id="${id}" data-version="${v.version}" class="stack"><label>Registered driver<select name="driverId"><option value="">Manual name / remove assignment</option>${(data.drivers||[]).map(d=>`<option value="${d.id}" ${v.driverId===d.id?'selected':''}>${esc(d.name)} · ${esc(d.employeeId||'')}</option>`).join('')}</select></label><label>Manual driver name (used when no registered driver is selected)<input name="driver" maxlength="120" value="${esc(v.driver)}" placeholder="Enter driver name" autocomplete="off"></label><small>Leave blank to remove the current assignment. This records the assignment only; it does not establish driver clearance.</small><div class="error" role="alert"></div><div class="form-footer"><button type="button" data-close="small-dialog">Cancel</button><button class="primary">Save driver</button></div></form>`);}


const duplicateLabels={unitNumber:'Vehicle number',vin:'VIN',driver:'Driver'};
function normalizedValue(v,key){let value=String(v[key]??'').trim().replace(/\s+/g,' ').toUpperCase();if(key==='vin')value=value.replace(/\s/g,'');if(key==='unitNumber'&&/^\d+$/.test(value))value=value.replace(/^0+(?=\d)/,'');return value;}
function registryVehicles(){return data.vehicles.filter(v=>page!=='inventory'||(filter==='disposed'?v.operationalState==='Disposed':v.operationalState!=='Disposed'));}
function duplicateGroups(key){const groups=new Map();for(const v of registryVehicles()){const value=normalizedValue(v,key);if(!value)continue;if(!groups.has(value))groups.set(value,{value,label:String(v[key]).trim(),count:0});groups.get(value).count++;}return [...groups.values()].filter(g=>g.count>1).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label,undefined,{numeric:true}));}
function duplicateCount(key){return duplicateGroups(key).reduce((n,g)=>n+g.count,0);}
function sortValue(v,key){
 if(key==='status'){const o=ownershipInfo(v);return o.label+(o.accounting?' Accounting asset':'');}
 if(key==='sources')return String(sourceKeys.filter(s=>sourceState(v,s)==='Listed').length).padStart(3,'0')+' '+sourceKeys.map(s=>sourceState(v,s)).join(' ');
 if(key==='review')return String(issues(v).length).padStart(6,'0')+' '+v.verificationStatus;
 if(key==='unitNumber')return v.unitNumber||'';
 return v[key]||'';
}
function sortedVehicles(rows){return [...rows].sort((a,b)=>{const av=String(sortValue(a,sortKey)),bv=String(sortValue(b,sortKey));if(!av||!bv){if(!av&&bv)return 1;if(av&&!bv)return -1;}const c=av.localeCompare(bv,undefined,{numeric:true,sensitivity:'base'});return c?(sortDirection==='asc'?c:-c):String(a.id).localeCompare(String(b.id));});}
function columnHeader(key,title,sortable=true){const count=duplicateLabels[key]?duplicateCount(key):0;return `<th aria-sort="${sortable&&sortKey===key?(sortDirection==='asc'?'ascending':'descending'):'none'}"><div class="column-controls">${sortable?`<button class="sort-button" data-sort="${key}" title="Sort ${title}">${title} <span aria-hidden="true">${sortKey===key?(sortDirection==='asc'?'↑':'↓'):'↕'}</span></button>`:title}${count?`<button class="duplicate-count" data-duplicates="${key}" title="${count} records share a ${duplicateLabels[key].toLowerCase()}; click to filter" aria-label="${count} duplicate ${duplicateLabels[key].toLowerCase()} instances">${count}</button>`:''}</div>${key==='driver'?`<button class="missing-count" data-without-driver="true">${registryVehicles().filter(v=>!normalizedValue(v,'driver')).length} without driver</button>`:''}</th>`;}
function duplicatesModal(key){const groups=duplicateGroups(key),count=duplicateCount(key),max=Math.max(1,...groups.map(g=>g.count));showSmall(`${duplicateLabels[key]} duplicates`, `<p><b>${count} duplicate instances</b> across ${groups.length} repeated values.</p><p class="muted">Counts include all records in each repeated group, across the full repository. Blank values are excluded. Matching ignores capitalization and extra spaces; numeric vehicle numbers also ignore leading zeros. Selecting a bar clears other filters to show every matching record.</p>${groups.length?`<button class="compact" data-duplicate-field="${key}" data-duplicate-value="*">Show all duplicates</button><div class="histogram">${groups.map(g=>`<button class="histogram-row" data-duplicate-field="${key}" data-duplicate-value="${esc(g.value)}"><span>${esc(g.label)}</span><meter min="0" max="${max}" value="${g.count}" aria-label="${esc(g.label)}: ${g.count} records"></meter><b>${g.count}</b></button>`).join('')}</div>`:'<div class="empty">No duplicate values found.</div>'}`);}
function sectionModal(id){const v=getV(id);showSmall('CCS Section',`<p><b>${esc(label(v))}</b> · ${esc(v.plate||v.vin)}</p><form id="section-form" data-id="${id}" data-version="${v.version}" class="stack"><label>Section<select name="section"><option value="">Not recorded</option>${['Services','Valet','Sales'].map(x=>`<option ${v.section===x?'selected':''}>${x}</option>`).join('')}</select></label><small>${esc(v.sectionSource||'Not recorded')}</small><div class="error" role="alert"></div><button class="primary">Save section</button></form>`);}

const dots=v=>`<div class="source-dots">${sourceKeys.map((s,i)=>{const state=sourceState(v,s);return `<span title="${sourceNames[s]}: ${state}" class="source-dot ${state==='Listed'?'present':state!=='Not listed'?'possible':''}">${['F','I','B','M','A','S'][i]}</span>`;}).join('')}</div>`;
function vehicleExportRows(){return filtered().map(v=>{const d=(data.drivers||[]).find(d=>d.id===v.driverId),source=data.sources.find(s=>s.id==='samsara'),se=evidence(v).filter(e=>e.sourceId==='samsara'&&(!source?.lastAcceptedUploadId||e.uploadId===source.lastAcceptedUploadId));return {...v,driverName:d?.name||v.driver||'',...Object.fromEntries(Object.entries(d||{}).map(([k,val])=>['driver_'+k,val])),ownershipStatus:ownershipInfo(v).label,accountingAssetStatus:sourceState(v,'balance'),inSamsara:sourceState(v,'samsara')==='Listed'?'Yes':'Not confirmed',samsaraStatus:sourceState(v,'samsara'),samsaraDeviceIds:se.map(e=>e.fields?.deviceId||'').filter(Boolean).join('; '),samsaraSerials:se.map(e=>e.fields?.serial||'').filter(Boolean).join('; '),...Object.fromEntries(sourceKeys.map(k=>['source_'+k,sourceState(v,k)])),openReviewCount:issues(v).length,openReviewItems:issues(v).map(i=>i.message+': '+(i.details||'')).join('; '),documents:data.documents.filter(d=>d.vehicleId===v.id).map(d=>d.category+': '+d.filename).join('; ')};});}
function driverExportRows(){return filteredDrivers().map(d=>({...d,assignedVehicles:data.vehicles.filter(v=>v.driverId===d.id||v.driver&&v.driver.toLowerCase()===d.name.toLowerCase()).map(v=>({vehicleNumber:v.unitNumber,vin:v.vin,plate:v.plate,operationalState:v.operationalState})),insuranceListed:driverListed(d)?'Yes':'Not confirmed',discrepancies:driverChecks(d).join('; ')}));}
function csvText(rows,baseHeaders=[]){const headers=[...new Set([...baseHeaders,...rows.flatMap(r=>Object.keys(r))])];const cell=value=>{let text=value===null||value===undefined?'':typeof value==='object'?JSON.stringify(value):String(value);if(/^[\s]*[=+@-]/.test(text)||/^[\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};return '\uFEFF'+[headers.map(cell).join(','),...rows.map(r=>headers.map(k=>cell(r[k])).join(','))].join('\r\n');}
function downloadCsv(name,rows,headers=[]){const url=URL.createObjectURL(new Blob([csvText(rows,headers)],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${rows.length} matching rows across all pages.`);}
function exportTable(kind,context){if(kind==='vehicles')downloadCsv('CCS-vehicles-filtered',vehicleExportRows(),['unitNumber','vin','plate','section','driverName','inSamsara']);else if(kind==='drivers')downloadCsv('CCS-drivers-filtered',driverExportRows(),['name','employeeId','role']);else if(kind==='reviews'){const ids=new Set(filtered().map(v=>v.id));downloadCsv('CCS-reviews-filtered',data.issues.filter(i=>i.status==='Open'&&ids.has(i.vehicleId)).map(i=>({...i,vehicleNumber:getV(i.vehicleId)?.unitNumber,vin:getV(i.vehicleId)?.vin,plate:getV(i.vehicleId)?.plate})),['vehicleNumber','vin','plate','message']);}else if(kind.startsWith('insurance-')){const report=context==='pending'?pendingSource?.insuranceComparison:data.insuranceComparison;downloadCsv('CCS-'+kind,report?.[kind.slice(10)]||[],['name','employeeId','locator']);}else if(kind==='source-review')downloadCsv('CCS-source-comparison',pendingSource?.rows||[],['locator','kind','status','message','targetId','fields','changes']);}
function toast(m){$('#toast').textContent=m;$('#toast').className='visible';setTimeout(()=>$('#toast').className='',5500);}
async function api(path,method='GET',body){let r;try{r=await fetch(path,{method,headers:body?{'Content-Type':'application/json','X-CCS-Token':data.token}:{},body:body?JSON.stringify(body):undefined});}catch{throw Error('Connection to CCS Fleet was lost. Wait briefly, then refresh. Check Source Comparison for a pending upload before retrying.');}const j=await r.json();if(r.status===401&&j.login){location.href=j.login;throw Error('Sign-in required.');}if(!r.ok)throw Error(j.error||'Request failed.');return j;}

async function previewUpload(body){const job=await api('/api/source-upload/jobs','POST',body);for(;;){await new Promise(r=>setTimeout(r,600));const state=await api('/api/source-upload/jobs/'+job.id);if(state.status==='failed')throw Error(state.error);if(state.status==='complete')return state.result;}}
function driverListed(d){if(data.insuranceComparison)return data.insuranceComparison.matchedIds.includes(d.id);const source=data.sources.find(s=>s.id==='drivers');return data.driverEvidence.some(e=>e.driverId===d.id&&e.sourceId==='drivers'&&(!source?.lastAcceptedUploadId||e.uploadId===source.lastAcceptedUploadId));}
function insuranceSummary(kind){const vehicle=kind==='vehicles',rows=vehicle?data.vehicles.filter(v=>v.operationalState!=='Disposed'):data.drivers;const missing=rows.filter(x=>vehicle?sourceState(x,'emc')!=='Listed':!driverListed(x));const groups=[...new Set(rows.map(x=>vehicle?(x.section||'Not recorded'):(x.market||'Not recorded')))];return `<section class="card"><div class="card-head"><div><h2>Insurance gaps · ${missing.length}</h2><p>Not listed in the latest insurance source; coverage needs confirmation.</p></div><button data-insurance-kind="${kind}" data-insurance-area="*">Show all ${missing.length}</button></div><div class="toolbar">${groups.sort().map(g=>`<button data-insurance-kind="${kind}" data-insurance-area="${esc(g)}">${esc(g)} · ${missing.filter(x=>(vehicle?(x.section||'Not recorded'):(x.market||'Not recorded'))===g).length}</button>`).join('')}</div></section>`;}
let driverArea='';

async function refresh(){data=await api('/api/bootstrap');if(data.setupRequired){location.href='/';return;}data.drivers=data.drivers||[];data.driverEvidence=data.driverEvidence||[];data.uploads=data.uploads||[];render();}
function nav(p){page=p;driverArea='';driverCheckFilter='';search='';filter='all';stateFilter='';ownershipFilter='';driverFilter='';sectionFilter='';duplicateField='';duplicateValue='';index=0;location.hash=p;render();}
function render(){
 document.body.dataset.role=data.user?.role||'admin';
 if($('#account'))$('#account').textContent=data.hosted?(data.user.email+' · '+data.user.role):'Local';
 $('#add-btn').hidden=page!=='inventory';
 $('#nav').innerHTML=navs.map(([p,i,n])=>`<button data-nav="${p}" class="${p===page?'active':''}"><span class="nav-icon">${i}</span>${n}</button>`).join('');$('#title').textContent=navs.find(n=>n[0]===page)?.[2]||'Vehicle register';content.innerHTML=({overview,inventory,review,sources,drivers:driversPage,activity}[page]||overview)();
}
function stat(name,n,note,icon,action,amber=false){return `<button class="stat ${amber?'amber':''}" data-stat="${action}"><span class="stat-icon">${icon}</span><span class="stat-label">${name}</span><strong>${n}</strong><small>${note}</small></button>`;}
function overview(){const vs=data.vehicles,active=vs.filter(v=>v.operationalState!=='Disposed'),verified=active.filter(v=>v.verificationStatus==='Verified').length,open=data.issues.filter(i=>i.status==='Open');return `<section class="hero"><div><span class="hero-label">BUILD A FLEET YOU CAN TRUST</span><h2>One place for every CCS vehicle.</h2><p>Collect the facts, compare the records, and verify each vehicle. Your source documents stay connected to every decision.</p></div><span class="pill">● Manual collection</span></section><div class="stats">${stat('Repository records',vs.length,`${vs.filter(v=>!v.vin).length} unresolved references · ${vs.filter(v=>v.operationalState==='Disposed').length} disposed`,'▤','all')}${stat('Verified vehicles',verified,'Physical verification required','✓','verified')}${stat('Open review items',open.length,`${active.filter(v=>issues(v).length).length} non-disposed records need review`,'◇','review',true)}${stat('Locations to collect',active.filter(v=>!v.location).length,'Current location not confirmed','⌖','location',true)}</div><div class="grid-two"><section class="card"><div class="card-head"><div><h2>Start with the gaps</h2><p>Turn source records into a reliable vehicle inventory.</p></div></div>${[['identity','Missing CCS vehicle numbers',active.filter(v=>!v.unitNumber).length,'Assign your internal vehicle number.'],['location','Current location missing',active.filter(v=>!v.location).length,'Confirm where the vehicle actually is.'],['insurance','Not listed by exact VIN in EMC',active.filter(v=>sourceState(v,'emc')!=='Listed').length,'Review the supplied September 25 list and current policy.'],['review','Conflicting or incomplete records',active.filter(v=>issues(v).length).length,'Resolve differences and document the decision.']].map(([f,n,c,t])=>`<div class="list-row"><div><button class="link" data-stat="${f}">${n}</button><p>${t}</p></div>${badge(c,c?'amber':'green')}</div>`).join('')}</section><section class="card"><div class="card-head"><div><h2>Source coverage</h2><p>Full-VIN matches to the current master records.</p></div></div>${sourceKeys.map(s=>`<div class="list-row"><div><b>${sourceNames[s]}</b><p>${s==='balance'?'Partial VIN matches need review':'Loaded reference records'}</p></div><strong>${vs.filter(v=>sourceState(v,s)==='Listed').length}${s==='balance'?` <small>+ ${vs.filter(v=>sourceState(v,s)==='Possible match').length} possible</small>`:''}</strong></div>`).join('')}</section></div><div class="notice">Driver assignments are recorded manually. Repository totals include unresolved references and potential VIN conflicts; they are not a verified physical vehicle count.</div>`;}
function filtered(){return sortedVehicles(registryVehicles().filter(v=>{const hay=[...Object.values(v).filter(x=>typeof x==='string'),...evidence(v).map(e=>JSON.stringify(e.raw))].join(' ').toLowerCase().replace(/[^a-z0-9]/g,'');return (!search||hay.includes(search.toLowerCase().replace(/[^a-z0-9]/g,'')))&&(!stateFilter||v.plateState===stateFilter)&&(!ownershipFilter||(ownershipFilter==='accounting'?ownershipInfo(v).accounting:ownershipInfo(v).key===ownershipFilter))&&(!driverFilter||(driverFilter==='assigned'?!!v.driver:!v.driver))&&(!sectionFilter||(sectionFilter==='unrecorded'?!v.section:v.section===sectionFilter))&&(!duplicateField||(duplicateValue==='*'?duplicateGroups(duplicateField).some(g=>g.value===normalizedValue(v,duplicateField)):normalizedValue(v,duplicateField)===duplicateValue))&&(filter==='all'||filter==='verified'&&v.verificationStatus==='Verified'||filter==='review'&&issues(v).length||filter==='location'&&!v.location||filter==='identity'&&!v.unitNumber||filter==='disposed'&&v.operationalState==='Disposed'||filter==='insurance'&&sourceState(v,'emc')!=='Listed'||filter==='samsara'&&sourceState(v,'samsara')!=='Listed'||filter==='no-source'&&withoutAssetSource(v));}));}
function toolbar(){return `<div class="toolbar"><input class="search" id="search" type="search" placeholder="Search VIN, plate, CCS number, source reference…" aria-label="Search vehicles" value="${esc(search)}"><select id="filter" aria-label="Record filter">${[['all','All records'],['review','Needs review'],['verified','Verified'],['identity','Missing CCS number'],['location','Missing location'],['insurance','Not listed in EMC'],['samsara','Not listed in Samsara'],['no-source','No lease / asset source'],['disposed','Disposed']].map(([v,t])=>`<option value="${v}" ${v===filter?'selected':''}>${t}</option>`).join('')}</select><select id="state-filter" aria-label="Plate state"><option value="">All plate states</option>${[...new Set(data.vehicles.map(v=>v.plateState).filter(Boolean))].sort().map(s=>`<option ${s===stateFilter?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="ownership-filter" aria-label="Ownership status"><option value="">All ownership statuses</option>${[['bancorp','Leased · Bancorp'],['moventum','Leased · Moventum / Union'],['lease','Other lease provider'],['owned','CCS owned'],['financed','Financed'],['accounting','Accounting asset / possible match'],['unknown','Ownership not confirmed']].map(([k,n])=>`<option value="${k}" ${ownershipFilter===k?'selected':''}>${n}</option>`).join('')}</select><select id="driver-filter" aria-label="Driver assignment"><option value="">All driver assignments</option><option value="assigned" ${driverFilter==='assigned'?'selected':''}>Driver assigned</option><option value="unassigned" ${driverFilter==='unassigned'?'selected':''}>No driver assigned</option></select><select id="section-filter" aria-label="CCS section"><option value="">All CCS sections</option>${['Services','Valet','Sales'].map(x=>`<option ${sectionFilter===x?'selected':''}>${x}</option>`).join('')}<option value="unrecorded" ${sectionFilter==='unrecorded'?'selected':''}>Section not recorded</option></select>${duplicateField?`<span class="active-filter">${esc(duplicateLabels[duplicateField])}: ${esc(duplicateValue==='*'?'all duplicates':duplicateValue)} <button data-clear-duplicates="true" aria-label="Clear duplicate filter">×</button></span>`:''}</div>`;}
function pager(total){return `<div class="pagination"><span>${total?`${index*25+1}–${Math.min((index+1)*25,total)}`:'0'} of ${total} records</span><span><button data-page="-1" ${index===0?'disabled':''}>← Previous</button><button data-page="1" ${(index+1)*25>=total?'disabled':''}>Next →</button></span></div>`;}
function vehicleTable(vs,title='Vehicle register',filters=true){return `<section class="card"><div class="card-head"><div><h2>${title}</h2><p>Master values are unverified until reviewed. Open a record to compare evidence.</p></div><button data-export-table="vehicles">Export filtered CSV ↓</button></div>${filters?toolbar():''}<div class="table-wrap"><table><thead><tr>${[['unitNumber','Vehicle / CCS number'],['vin','VIN'],['plate','License plate'],['location','Current location'],['section','CCS Section'],['status','Status'],['driver','Driver'],['sources','Sources'],['review','Review status']].map(([k,n])=>columnHeader(k,n,filters)).join('')}</tr></thead><tbody>${vs.map(v=>`<tr><td><button class="link" data-open="${v.id}">${esc(label(v))}</button><small class="vehicle-name">${esc([v.year,v.make,v.model].filter(Boolean).join(' ')||'Description needed')}</small>${v.operationalState==='Disposed'?badge('Disposed','red'):''}</td><td class="mono">${esc(v.vin||'Full VIN needed')}</td><td><b>${esc(v.plate||'Not recorded')}</b><small>${esc(v.plateState)}</small></td><td>${esc(v.location||'Not confirmed')}<small>${esc(v.region)}</small></td><td><button class="section-cell" data-section="${v.id}" title="Edit CCS section">${esc(v.section||'Not recorded')} <span aria-hidden="true">✎</span></button></td><td>${ownershipCell(v)}</td><td>${driverCell(v)}</td><td>${dots(v)}</td><td>${reviewStatus(v)}${page==='inventory'?`<button class="compact top-space" data-disposal="${v.id}">${v.operationalState==='Disposed'?'Restore vehicle':'Mark disposed'}</button>`:''}</td></tr>`).join('')}</tbody></table>${!vs.length?'<div class="empty">No records match these filters.</div>':''}</div></section>`;}
function withoutAssetSource(v){return ['bancorp','moventum','balance'].every(s=>sourceState(v,s)==='Not listed');}
function vehicleGapSummary(){const rows=data.vehicles.filter(v=>v.operationalState!=='Disposed');return `<div class="vehicle-gap-grid">${[['insurance','Insurance gaps','Not listed in the latest insurance source.',v=>sourceState(v,'emc')!=='Listed'],['samsara','Vehicles not in Samsara','No confirmed equipment match in the latest accepted CSV.',v=>sourceState(v,'samsara')!=='Listed'],['no-source','Vehicles without a source','Absent from Bancorp, Moventum and the accounting asset sheet.',withoutAssetSource]].map(([key,title,note,test])=>{const missing=rows.filter(test);return `<section class="card"><div class="card-head"><div><h3>${title} · ${missing.length}</h3><p>${note}</p></div><button data-gap="${key}" data-gap-area="*">Show all ${missing.length}</button></div><div class="toolbar">${[...new Set(rows.map(v=>v.section||'Not recorded'))].sort().map(area=>`<button data-gap="${key}" data-gap-area="${esc(area)}">${esc(area)} · ${missing.filter(v=>(v.section||'Not recorded')===area).length}</button>`).join('')}</div></section>`;}).join('')}</div>`;}
function registryTabs(){const disposed=data.vehicles.filter(v=>v.operationalState==='Disposed').length;return `<div class="actions top-space" role="group" aria-label="Vehicle storage"><button data-registry-view="current" class="${filter!=='disposed'?'primary':''}" aria-pressed="${filter!=='disposed'}">Current vehicles (${data.vehicles.length-disposed})</button><button data-registry-view="disposed" class="${filter==='disposed'?'primary':''}" aria-pressed="${filter==='disposed'}">Disposed vehicles (${disposed})</button></div>`;}
function disposalModal(id){const v=getV(id),restore=v.operationalState==='Disposed';showSmall(restore?'Restore vehicle':'Move to disposed vehicles',`<p><b>${esc(label(v))}</b> · ${esc(v.plate||v.vin)}</p><div class="notice">${restore?'Return this vehicle to the current register.':'This vehicle will leave the current register and remain in Disposed vehicles. Documents, source evidence, driver history and notes are retained.'}</div><form id="disposal-form" data-id="${v.id}" data-version="${v.version}" class="stack"><input type="hidden" name="operationalState" value="${restore?'Unknown':'Disposed'}"><label>${restore?'Restoration':'Disposal'} note<textarea name="note" required minlength="3" rows="3" placeholder="Reason and any relevant details"></textarea></label><div class="error" role="alert"></div><div class="form-footer"><button type="button" data-close="small-dialog">Cancel</button><button class="primary">${restore?'Restore to current register':'Confirm disposal'}</button></div></form>`);}
function inventory(){const vs=filtered();return `${registryTabs()}${filter==='disposed'?'<div class="notice">Disposed vehicles are stored here with their documents, source evidence and history. Open a record to inspect it, or restore it to the current register.</div>':vehicleGapSummary()}<div class="notice">Sources: F = Fleet Sheet · I = EMC insurance · B = Bancorp · M = Moventum · A = Accounting · S = Samsara. Blue means listed; amber means a tentative or supporting match. Use Add driver to record an assignment, then the pencil to edit it.</div>${vehicleTable(vs.slice(index*25,index*25+25),filter==='disposed'?'Disposed vehicles':'Current vehicles')}${pager(vs.length)}`;}
function review(){const vs=filtered(),ids=new Set(vs.map(v=>v.id)),items=data.issues.filter(i=>i.status==='Open'&&ids.has(i.vehicleId));return `<div class="notice amber">Review items identify source differences and missing information. Resolving a note does not verify the vehicle; complete the vehicle checklist after reviewing the evidence.</div><section class="card"><div class="card-head"><div><h2>Open review queue</h2><p>${items.length} items · original evidence remains unchanged</p></div><button data-export-table="reviews">Export filtered CSV ↓</button></div>${toolbar()}<div class="table-wrap"><table><thead><tr><th>Vehicle</th><th>Review item</th><th>Evidence / detail</th><th></th></tr></thead><tbody>${items.slice(index*25,index*25+25).map(i=>`<tr><td><button class="link" data-open="${i.vehicleId}">${esc(label(getV(i.vehicleId)))}</button><small class="mono">${esc(getV(i.vehicleId)?.vin)}</small></td><td><b>${esc(i.message)}</b><small>${esc(i.field)}</small></td><td>${esc(i.details||'Review and update the master record.')}</td><td><button class="compact" data-resolve="${i.id}">Resolve</button></td></tr>`).join('')}</tbody></table>${!items.length?'<div class="empty">No open items in this view.</div>':''}</div>${pager(items.length)}</section>`;}
function sourceFreshness(s,at=Date.now()){if(!s.lastUploadedAt)return {overdue:true,days:null,label:'No upload date recorded'};const days=Math.floor((at-Date.parse(s.lastUploadedAt))/86400000);return {overdue:days>=30,days,label:days>=30?`${days} days old · overdue`:`${Math.max(0,days)} days old · refresh monthly`};}
function sourceUploadCard(s){const c=data.sourceTypes?.[s.id],fresh=sourceFreshness(s);return `<section class="card source-card ${fresh.overdue?'source-overdue':''}"><div class="status-line">${badge(s.status,s.status==='Pending review'?'amber':s.status==='Loaded'?'blue':'')}${s.rowCount?`<small>${s.rowCount} source rows</small>`:''}</div><h3>${esc(c?.title||s.name)}</h3><p>${esc(s.note)}</p>${c?`<div class="source-upload-controls"><button class="primary compact" data-source-upload="${s.id}">${esc(c.label)}</button><span class="upload-date ${fresh.overdue?'overdue':''}"><b>Last upload:</b> ${s.lastUploadedAt?esc(fmt(s.lastUploadedAt)):'Not recorded'}<small>${fresh.label}</small></span></div><small class="source-file">${esc(s.lastFilename||s.name)}</small><small>Last approved comparison: ${s.lastAcceptedAt?esc(fmt(s.lastAcceptedAt)):'Original references / no reviewed upload yet'}</small>${s.pendingUploadId?`<button class="compact top-space" data-resume-upload="${s.pendingUploadId}">Review pending upload</button>`:''}${s.lastAcceptedUploadId?` <a href="/api/source-upload/${s.lastAcceptedUploadId}/download" download>Download latest accepted file</a>`:''}`:''}</section>`;}
function insuranceComparisonView(report,context='saved'){if(!report)return '<div class="notice">Upload the insured-driver list in Source Comparison to see insurance additions and removals.</div>';return `<details class="card insurance-collapse"><summary>Insurance driver reconciliation <span class="muted">· ${report.add.length} to add · ${report.remove.length} to review for removal · ${report.review.length} ambiguous · click to expand / collapse</span></summary><div class="dialog-body"><p>Compared with the latest accepted CC roster. These are recommendations; no insurance changes are sent.</p>${[['add','Add to insurance',report.add,'CC drivers missing from insurance'],['remove','Review for removal from insurance',report.remove,'Insurance names not in the current CC roster'],['review','Resolve ambiguous names',report.review,'Multiple CC identities match; resolve before adding or removing']].map(([key,title,rows,note])=>`<details class="insurance-sublist"><summary>${title} (${rows.length})</summary><p>${note}</p><button data-export-table="insurance-${key}" data-report-context="${context}">Export this list CSV ↓</button><div class="insurance-scroll">${rows.map(r=>`<div class="list-row">${esc(r.name)}${r.employeeId?' · '+esc(r.employeeId):''}</div>`).join('')||'<p>None</p>'}</div></details>`).join('')}</div></details>`;}

function sources(){return `<div class="notice">All imports live here. Upload each source monthly; dates turn red after 30 days. One CC CSV checks both registries. Review discrepancies before changing existing data.</div>${insuranceComparisonView(data.insuranceComparison)}<div class="source-grid">${data.sources.filter(s=>s.id!=='driverSystem').map(sourceUploadCard).join('')}</div><section class="card"><div class="card-head"><h2>Vehicle supporting documents</h2></div><form id="document-form" class="stack"><label>Vehicle<select name="vehicleId" required>${data.vehicles.map(v=>`<option value="${v.id}">${esc(label(v))} · ${esc(v.vin)}</option>`).join('')}</select></label><label>Category<select name="category"><option>Registration</option><option>Insurance</option><option>Title / lease</option><option>Condition photos</option><option>Service record</option><option>Other</option></select></label><label>File (PDF, PNG or JPEG; 5 MB)<input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg" required></label><div class="error" role="alert"></div><button class="primary">Upload supporting document</button></form></section>`;}

function activity(){return `<section class="card"><div class="card-head"><div><h2>Shared fleet database</h2><p>SQLite database · vehicle records, source evidence, audit history and uploaded documents.</p></div></div><div class="dialog-body"><div class="actions"><a href="/api/backup" download><button class="primary">Download complete database backup</button></a><button data-nav="inventory">Open Vehicle Registry to export filtered CSV</button></div><p class="muted">Administrators: download a backup before major imports and keep a copy outside Render. Daily consistent SQLite backups are retained on the persistent disk. Follow HOSTING-GUIDE.txt for recovery; never replace a live database. Table CSV exports follow the current filters and include all matching pages. Vehicle exports include linked driver and source details.</p></div></section><section class="card"><div class="card-head"><div><h2>Change history</h2><p>Latest 300 events. Full before-and-after values remain in the database.</p></div></div><div class="table-wrap"><table><thead><tr><th>When</th><th>Action</th><th>Vehicle</th><th>Note</th></tr></thead><tbody>${data.audit.map(a=>`<tr><td>${esc(new Date(a.time).toLocaleString())}</td><td>${badge(a.action)}</td><td>${a.vehicleId&&getV(a.vehicleId)?`<button class="link" data-open="${a.vehicleId}">${esc(label(getV(a.vehicleId)))}</button>`:'Workspace'}</td><td>${esc(a.note)}</td></tr>`).join('')}</tbody></table></div></section>`;}
const input=(title,key,v,type='text',attrs='')=>`<label>${title}<input name="${key}" type="${type}" value="${esc(v[key])}" ${attrs}></label>`;
const select=(title,key,v,options)=>`<label>${title}<select name="${key}">${options.map(x=>`<option ${x===v[key]?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
function openVehicle(id,t='profile'){selected=id;tab=t;const v=id?getV(id):{};drawer.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">VEHICLE RECORD</span><h2 id="dialog-title">${esc(id?label(v):'Add a CCS vehicle')}</h2><small>${esc(v.vin||'Manually collect the vehicle details')}</small></div><button class="close" data-close="drawer" aria-label="Close vehicle">×</button></div>${id?`<div class="tabs">${[['profile','Master record'],['evidence','Source evidence'],['verify','Verification'],['docs','Documents']].map(([k,n])=>`<button data-tab-select="${k}" class="${tab===k?'active':''}">${n}</button>`).join('')}</div>`:''}<div class="dialog-body">${({profile:profileForm,evidence:evidenceView,verify:verifyForm,docs:docsView}[tab])(v)}</div>`;if(!drawer.open)drawer.showModal();}
function profileForm(v){return `<form id="vehicle-form"><div class="status-line">${v.id?reviewStatus(v):badge('Manual entry','blue')}${badge(v.driver?'Driver: '+v.driver:'No driver assigned')}<small>Saving changes resets verification.</small></div><div class="form-grid"><div class="section-label wide">01 / IDENTITY</div>${input('CCS vehicle number','unitNumber',v)}${input('VIN (17 characters, or leave blank)','vin',v,'text','maxlength="17"')}${input('Year','year',v,'number','min="1900" max="2100"')}${input('Make','make',v)}${input('Model / provisional description','model',v)}${input('License plate','plate',v)}${input('Plate state','plateState',v,'text','maxlength="2"')}${input('Ownership / lease / financing','ownership',v)}<div class="section-label wide">02 / LOCATION & STATUS</div>${input('Confirmed current location (city, state)','location',v)}${input('Operating region','region',v)}${select('CCS Section','section',v,['','Services','Valet','Sales'])}${select('Operational status','operationalState',v,['Unknown','Available','Maintenance','Out of service','Disposed'])}${select('Inspected condition','condition',v,['Unknown','Good','Needs attention','Unsafe'])}<div class="section-label wide">03 / REGISTRATION & INSURANCE</div>${input('Registration expiry','registrationExpiry',v,'date')}${input('Confirmed insurance expiry','insuranceExpiry',v,'date')}<div class="section-label wide">04 / MAINTENANCE, FUEL & EQUIPMENT</div>${input('Odometer (miles)','odometer',v,'number','min="0"')}${input('Odometer recorded on','odometerDate',v,'date')}${input('Last oil change date','lastOilChange',v,'date')}${input('Last oil change mileage','lastOilMileage',v,'number','min="0"')}${input('Next service date','pmDueDate',v,'date')}${input('Next service mileage','pmDueMiles',v,'number','min="0"')}${input('Tire condition','tireCondition',v)}${input('Mechanical observations','mechanicalNotes',v)}${input('Fuel card provider','fuelProvider',v)}${input('Fuel card last four digits','fuelCard',v,'text','maxlength="4"')}${input('Toll transponder number','tollTag',v)}<label>Driver assignment<input value="${esc(v.driver)}" disabled aria-label="Current driver"><small>Use the Driver column to add or edit an assignment.</small></label><label class="wide">Notes<textarea name="notes" rows="3">${esc(v.notes)}</textarea></label></div><div class="error" role="alert"></div><div class="form-footer">${v.id?`<button type="button" data-merge="${v.id}" class="danger">Reconcile duplicate</button>`:''}<button type="button" data-close="drawer">Cancel</button><button class="primary">Save vehicle</button></div></form>`;}
function evidenceView(v){const es=evidence(v),is=data.issues.filter(i=>i.vehicleId===v.id);return `<div class="notice">Initial master values favor the Fleet Sheet, then lease records, then EMC. Source values are preserved below. Current location and driver were not inferred.</div><h3>Review items</h3>${is.length?is.map(i=>`<div class="evidence-card"><div class="list-row"><div><b>${esc(i.message)}</b><p>${esc(i.details)}</p>${i.resolution?`<small>${esc(i.resolution)}</small>`:''}</div>${i.status==='Open'?`<button class="compact" data-resolve="${i.id}">Resolve</button>`:badge('Resolved','green')}</div></div>`).join(''):'<p class="muted">No outstanding source conflicts recorded.</p>'}<div class="card-head"><h3>Source evidence (${es.length})</h3><button class="compact" data-add-evidence="${v.id}">＋ Add evidence</button></div>${es.map(e=>`<div class="evidence-card"><h3>${esc(data.sources.find(s=>s.id===e.sourceId)?.name||e.sourceId)}</h3><div class="status-line">${badge(e.match,/suffix/i.test(e.match)?'amber':'blue')}<small>${esc(e.locator)}</small>${e.image?`<a target="_blank" rel="noopener" href="${esc(e.image)}">View source image ↗</a>`:''}</div><details><summary>View original source values</summary><dl class="kv">${Object.entries(e.raw).map(([k,x])=>`<dt>${esc(k)}</dt><dd>${esc(typeof x==='object'?JSON.stringify(x):x)}</dd>`).join('')}</dl></details></div>`).join('')}`;}
function verifyForm(v){return `<form id="verify-form"><div class="notice amber">Only check items you have personally reviewed. Complete verification requires all eight checks, supporting master details, and no open review items. Driver assignments are excluded.</div><div class="status-line">${reviewStatus(v)}${v.verifiedBy?`<small>Last reviewer: ${esc(v.verifiedBy)} ${v.verifiedAt?'· '+fmt(v.verifiedAt):''}</small>`:''}</div>${Object.entries(checks).map(([k,[title,desc]])=>`<label class="check"><input type="checkbox" name="${k}" ${v.checks?.[k]?'checked':''}><span><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}<div class="stack top-space"><label>Reviewer name<input name="reviewer" required minlength="2" value="${esc(v.verifiedBy)}"></label><label>Evidence / verification note<textarea name="note" required minlength="10" rows="3">${esc(v.verificationNote)}</textarea></label></div><div class="error" role="alert"></div><div class="form-footer"><button class="primary">Save verification progress</button></div></form>`;}
function docsView(v){const docs=data.documents.filter(d=>d.vehicleId===v.id);return `<div class="notice">Attach registrations, insurance cards, condition photos or service records. PDF, PNG and JPEG up to 5 MB per file. Files are stored inside the local database.</div><div class="file-list">${docs.map(d=>`<div class="list-row"><div><b>${esc(d.filename)}</b><p>${esc(d.category)} · ${fmt(d.createdAt)} · ${Math.round(d.bytes/1024)} KB</p></div><a href="/api/documents/${d.id}" download>Download ↓</a></div>`).join('')||'<div class="empty">No vehicle documents attached yet.</div>'}</div><p class="muted">Add supporting documents in Source Comparison.</p>`;}
function showSmall(title,body){small.classList.remove('wide-dialog');small.innerHTML=`<div class="dialog-head"><h2 id="small-title">${title}</h2><button class="close" data-close="small-dialog" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>`;if(!small.open)small.showModal();}
function importModal(sourceId='cc'){sourceUploadModal(sourceId);}
function sourceUploadModal(sourceId){const c=data.sourceTypes?.[sourceId];if(!c){toast('Refresh the app after updating the server.');return;}showSmall('Upload source for comparison',`<div class="notice">Choose the original report. Existing trucks and drivers are checked before any master changes. You will review discrepancies and approve changes on the next screen.</div><form id="source-upload-form" class="stack"><label>Source<select name="sourceId" id="upload-source">${Object.entries(data.sourceTypes).filter(([id])=>id!=='driverSystem').map(([id,x])=>`<option value="${id}" ${id===sourceId?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><label id="upload-file-label">${esc(c.label)}<input name="file" type="file" accept="${c.accept}" required></label><small><a href="/driver-register-template.csv" download>Driver Register CSV template ↓</a></small><small id="upload-format-help">Maximum 30 MB. Word images and scanned PDFs may take longer to read. OCR VINs must be checked against the document.</small><div class="error" role="alert"></div><div id="upload-progress" role="status"></div><button class="primary">Upload and check existing records</button></form>`);}
async function fileBase64(file){if(file.size>30*1024*1024)throw Error('Source files must be under 30 MB.');return await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Could not read this file.'));r.readAsDataURL(file);});}
async function resumeUpload(id){pendingSource=await api('/api/source-upload/'+id);sourceReviewModal();}
function sourceReviewModal(){const u=pendingSource;const count=status=>u.rows.filter(r=>r.status===status).length;showSmall('Review source discrepancies',`<div class="notice"><b>${esc(u.filename)}</b><br>${count('changes')} changed rows · ${count('new')} new candidates · ${count('matched')} matches · ${count('blocked')} blocked rows. Existing values stay unchanged unless you select Apply changes. New records require Add record.</div>${u.insuranceComparison?insuranceComparisonView(u.insuranceComparison,'pending'):''}${u.warnings.map(w=>`<p class="warning-text">${esc(w)}</p>`).join('')}${u.missingVehicleIds?.length?`<p class="warning-text">${u.missingVehicleIds.length} previously listed vehicles are missing from this report. They will be flagged for review; none will be deleted.</p>`:''}${u.missingDriverIds?.length?`<p class="warning-text">${u.missingDriverIds.length} registered drivers are not matched in this export. After approval they leave the active CC register; history is retained.</p>`:''}<div class="actions top-space">${u.sourceId==='cc'?'<button data-select-driver-adds="true">Select new drivers</button><button data-select-assignments="true">Select unambiguous assignments</button>':''}<button data-keep-source-values="true">Keep all existing values</button><button data-export-table="source-review">Export comparison CSV ↓</button></div><form id="source-review-form"><div class="review-table-wrap"><table class="upload-review-table"><thead><tr><th>Record / source row</th><th>Match and discrepancies</th><th>Your decision</th></tr></thead><tbody>${u.rows.map(r=>{const isDriver=['driver','insuredDriver'].includes(r.kind),v=r.targetId?(isDriver?data.drivers.find(d=>d.id===r.targetId):getV(r.targetId)):null;const options=isDriver?data.drivers:data.vehicles;const needsMatch=r.status==='blocked'||r.status==='unmatched'||r.manuallyMatched;return `<tr><td><b>${esc(r.kind==='assignment'?r.driverName:r.fields.name||r.fields.vin||r.raw.description||r.fields.vinSuffix||'Source row')}</b><small>${esc(r.kind)} · ${esc(r.locator)}</small>${r.fields.role?`<small>Role: ${esc(r.fields.role)}</small>`:''}${r.kind==='vehicle'&&r.status==='blocked'?`<label class="review-correction">Correct VIN<input data-correct-vin="${r.key}" value="${esc(r.fields.vin)}" maxlength="17"></label>`:''}</td><td>${badge(r.status,r.status==='blocked'?'red':r.status==='changes'||r.status==='new'?'amber':'blue')}<p>${esc(r.message)}</p>${v?`<small>Matched: ${esc(isDriver?v.name:label(v))}</small>`:''}${r.changes.length?`<dl class="diff-list">${r.changes.map(d=>`<dt>${esc(d.field)}</dt><dd><span class="diff-old">${esc(d.before||'(blank)')}</span> → <strong>${esc(d.after)}</strong></dd>`).join('')}</dl>`:''}${r.checks?`<dl class="diff-list">${r.checks.map(d=>`<dt>${esc(d.field)}</dt><dd>Saved: ${esc(d.existing||'(blank)')} · CC: ${esc(d.reported||'(blank)')}</dd>`).join('')}</dl>`:''}${needsMatch?`<label class="review-correction">Match an existing ${isDriver?'driver':'truck'}<select data-match-row="${r.key}"><option value="">Keep unresolved</option>${options.map(x=>`<option value="${x.id}" ${u.overrides?.[r.key]?.targetId===x.id?'selected':''}>${esc(isDriver?x.name+' · '+(x.employeeId||''):label(x)+' · '+x.vin+' · '+x.plate)}</option>`).join('')}</select></label>`:''}</td><td><select name="${r.key}" ${r.status==='blocked'?'disabled':''}><option value="keep">Keep existing / no add</option>${r.status==='new'?'<option value="add">Add record</option>':''}${r.targetId&&r.changes.length&&r.status!=='blocked'?'<option value="apply">Apply listed changes</option>':''}</select>${r.kind==='assignment'?'<small>Clear matches link automatically after driver data is saved. Conflicting assignments require explicit review.</small>':''}</td></tr>`;}).join('')}</tbody></table></div><div class="notice top-space">Confirming saves the source file and comparison evidence. Each row defaults to keeping saved values. Saved driver VIN / plate matches automatically link the registries; conflicting assignments stay unchanged. Applying a source change resets the vehicle’s verification. A source listing does not establish driver clearance.</div><label class="check"><input type="checkbox" name="confirmed" required><span>I reviewed these discrepancies and approve only the selected changes.</span></label><div class="error" role="alert"></div><div class="form-footer"><button type="button" data-recheck-upload="true">Recheck matches / corrections</button><button id="approve-upload" class="primary">Confirm reviewed upload</button></div></form>`);small.classList.add('wide-dialog');}
function driverChecks(d){const messages=(data.driverLinkChecks||[]).filter(x=>x.driverId===d.id&&(x.reason||x.warning)).map(x=>x.reason||x.warning),byVIN=data.vehicles.filter(v=>d.reportedVin&&v.vin===d.reportedVin),byPlate=data.vehicles.filter(v=>d.reportedPlate&&String(v.plate).replace(/[^A-Za-z0-9]/g,'').toUpperCase()===String(d.reportedPlate).replace(/[^A-Za-z0-9]/g,'').toUpperCase());if(d.reportedVin&&!byVIN.length)messages.push('VIN not in vehicle register');if(d.reportedPlate&&!byPlate.length)messages.push('Plate not in vehicle register');if(byVIN.length===1&&d.reportedPlate&&String(byVIN[0].plate).replace(/[^A-Za-z0-9]/g,'').toUpperCase()!==String(d.reportedPlate).replace(/[^A-Za-z0-9]/g,'').toUpperCase())messages.push('VIN / plate discrepancy');const source=data.sources.find(s=>s.id==='cc');if(source?.lastAcceptedUploadId&&!data.driverEvidence.some(e=>e.driverId===d.id&&e.sourceId==='cc'&&e.uploadId===source.lastAcceptedUploadId))messages.push('Not in latest CC export');return messages;}
function filteredDrivers(){let rows=(data.drivers||[]).filter(d=>(!driverArea||(d.market||'Not recorded')===driverArea)&&(!driverSearch||Object.values(d).join(' ').toLowerCase().includes(driverSearch.toLowerCase()))&&(!driverCheckFilter||(driverCheckFilter==='insurance'?!driverListed(d):driverCheckFilter==='issues'?driverChecks(d).length:!data.vehicles.some(v=>v.driverId===d.id||v.driver&&v.driver.toLowerCase()===d.name.toLowerCase()))));rows.sort((a,b)=>String(a[driverSortKey]||'').localeCompare(String(b[driverSortKey]||''),undefined,{numeric:true,sensitivity:'base'})*(driverSortDirection==='asc'?1:-1));return rows;}
function driversPage(){const rows=filteredDrivers();return `${insuranceSummary('drivers')}<div class="notice">CC is the source of truth for this register. Maintain driver records through the CC upload in Source Comparison.</div><section class="card"><div class="card-head"><div><h2>Driver Register (${data.drivers.length})</h2><p>Unique people, source checks, reported vehicles and confirmed assignments.</p></div><button data-export-table="drivers">Export filtered CSV ↓</button></div><div class="toolbar"><input id="driver-search" class="search" type="search" value="${esc(driverSearch)}" placeholder="Search name, employee number, role, VIN or plate" aria-label="Search drivers"><select id="driver-check-filter"><option value="">All drivers</option><option value="insurance" ${driverCheckFilter==='insurance'?'selected':''}>Insurance listing not confirmed</option><option value="issues" ${driverCheckFilter==='issues'?'selected':''}>Source discrepancies</option><option value="unassigned" ${driverCheckFilter==='unassigned'?'selected':''}>No confirmed vehicle assignment</option></select></div><div class="table-wrap"><table><thead><tr>${[['name','Name'],['employeeId','Employee #'],['role','CC role'],['reportedVin','CC VIN'],['reportedPlate','CC plate'],['canDrive','CC Can Drive']].map(([k,n])=>`<th><button class="sort-button" data-driver-sort="${k}">${n} ${driverSortKey===k?(driverSortDirection==='asc'?'↑':'↓'):'↕'}</button></th>`).join('')}<th>Assigned CCS vehicle</th><th>Checks / insurance listing</th><th></th></tr></thead><tbody>${rows.map(d=>{const assigned=data.vehicles.filter(v=>v.driverId===d.id||v.driver&&v.driver.toLowerCase()===d.name.toLowerCase()),check=driverChecks(d),insurance=data.sources.find(s=>s.id==='drivers'),listed=driverListed(d);return `<tr><td><b>${esc(d.name)}</b><small>${esc(d.email||'')}</small></td><td>${esc(d.employeeId)}</td><td>${esc(d.role)}${d.systemRole?`<small>System role: ${esc(d.systemRole)}</small>`:''}<small>${esc(d.market||'')}</small></td><td class="mono">${esc(d.reportedVin||'Not reported')}</td><td>${esc(d.reportedPlate||'Not reported')}</td><td>${esc(d.canDrive||'Not reported')}<small>Drives CCS: ${esc(d.drivesCCS||'Not reported')}</small></td><td>${assigned.map(v=>`<button class="link" data-open="${v.id}">${esc(label(v))}</button>`).join('<br>')||'Not assigned'}</td><td>${check.map(x=>badge(x,'amber')).join(' ')||badge('No identifier discrepancy','blue')}<small>${listed?'Listed in supplied driver insurance source':'Insurance listing not confirmed'}</small></td><td><button class="compact" data-driver-details="${d.id}">View source details</button></td></tr>`;}).join('')}</tbody></table>${!rows.length?'<div class="empty">No drivers match. Manage imports in Source Comparison.</div>':''}</div></section>`;}
function driverDetails(id){const d=data.drivers.find(x=>x.id===id);showSmall('Driver source details',`<h3>${esc(d.name)}</h3><dl class="kv">${Object.entries(d).filter(([k])=>!['id','version'].includes(k)).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><h3 class="top-space">Source history</h3>${data.driverEvidence.filter(e=>e.driverId===id).map(e=>`<div class="evidence-card"><b>${esc(data.sources.find(s=>s.id===e.sourceId)?.name)}</b><small>${esc(e.locator)}</small><dl class="kv">${Object.entries(e.fields).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl></div>`).join('')}`);}

function resolveModal(id){const i=data.issues.find(i=>i.id===id);showSmall('Resolve review item',`<p><b>${esc(i.message)}</b></p><p class="muted">${esc(i.details)}</p><div class="notice">Correct the master record as needed, then record your decision here. Source evidence is retained.</div><form id="resolve-form" data-id="${id}" class="stack"><label>Resolution and evidence<textarea name="note" required minlength="10" rows="4"></textarea></label><div class="error" role="alert"></div><button class="primary">Mark resolved</button></form>`);}
function mergeModal(id){const v=getV(id);showSmall('Reconcile duplicate records',`<div class="notice amber">The selected destination keeps its master values. All source evidence, review items and documents move to it. This record is archived, and the full merge is recorded in history. Confirm the VIN against physical evidence first.</div><p>Record to archive: <b>${esc(label(v))}</b> · <span class="mono">${esc(v.vin)}</span></p><form id="merge-form" data-id="${id}" class="stack"><label>Keep this destination record<select name="targetId" required><option value="">Choose the confirmed master…</option>${data.vehicles.filter(x=>x.id!==id).map(x=>`<option value="${x.id}">${esc(label(x))} — ${esc(x.vin||x.model)}</option>`).join('')}</select></label><label>Why are these the same vehicle?<textarea name="note" required minlength="10"></textarea></label><div class="error" role="alert"></div><button class="primary">Merge evidence and archive duplicate</button></form>`);}
document.addEventListener('click',async event=>{const el=event.target.closest('button,[data-open]');if(!el)return;try{
 if(el.dataset.gap){nav('inventory');filter=el.dataset.gap;sectionFilter=el.dataset.gapArea==='*'?'':el.dataset.gapArea==='Not recorded'?'unrecorded':el.dataset.gapArea;render();}
 if(el.dataset.registryView){nav('inventory');filter=el.dataset.registryView==='disposed'?'disposed':'all';render();}
 if(el.dataset.disposal)disposalModal(el.dataset.disposal);
 if(el.dataset.exportTable)exportTable(el.dataset.exportTable,el.dataset.reportContext);
 if(el.dataset.nav)nav(el.dataset.nav);
 if(el.dataset.stat){const f=el.dataset.stat;nav(f==='review'?'review':'inventory');filter=f==='review'?'all':f;render();}
 if(el.dataset.open)openVehicle(el.dataset.open,el.dataset.tab||'profile');
 if(el.dataset.close)$('#'+el.dataset.close).close();
 if(el.dataset.tabSelect)openVehicle(selected,el.dataset.tabSelect);
 if(el.dataset.page){index+=Number(el.dataset.page);render();}
 if(el.dataset.insuranceKind){if(el.dataset.insuranceKind==='vehicles'){nav('inventory');filter='insurance';sectionFilter=el.dataset.insuranceArea==='*'?'':el.dataset.insuranceArea==='Not recorded'?'unrecorded':el.dataset.insuranceArea;}else{nav('drivers');driverCheckFilter='insurance';driverArea=el.dataset.insuranceArea==='*'?'':el.dataset.insuranceArea;driverSearch='';}render();}
 if(el.dataset.sourceUpload)sourceUploadModal(el.dataset.sourceUpload);
 if(el.dataset.resumeUpload)await resumeUpload(el.dataset.resumeUpload);
 if(el.dataset.reviewInitialCc){el.disabled=true;try{pendingSource=await previewUpload({initial:true});await refresh();sourceReviewModal();}finally{el.disabled=false;}}
 if(el.dataset.driverDetails)driverDetails(el.dataset.driverDetails);
 if(el.dataset.driverSort){if(driverSortKey===el.dataset.driverSort)driverSortDirection=driverSortDirection==='asc'?'desc':'asc';else{driverSortKey=el.dataset.driverSort;driverSortDirection='asc';}render();}
 if(el.dataset.newDriver)showSmall('Add driver to register',`<form id="new-driver-form" class="stack"><label>Name<input name="name" required minlength="2"></label><label>Employee number<input name="employeeId"></label><label>Role<input name="role"></label><label>Email<input name="email" type="email"></label><div class="error" role="alert"></div><button class="primary">Add driver</button></form>`);
 if(el.dataset.selectDriverAdds)for(const row of pendingSource.rows.filter(r=>r.kind==='driver'&&r.status==='new'))small.querySelector(`[name="${row.key}"]`).value='add';
 if(el.dataset.selectAssignments)for(const row of pendingSource.rows.filter(r=>r.kind==='assignment'&&r.status==='changes'&&!r.assignmentConflict&&r.checks?.every(c=>String(c.existing||'').replace(/[^a-z0-9]/gi,'').toUpperCase()===String(c.reported||'').replace(/[^a-z0-9]/gi,'').toUpperCase())))small.querySelector(`[name="${row.key}"]`).value='apply';
 if(el.dataset.keepSourceValues)for(const select of small.querySelectorAll('#source-review-form select[name]'))select.value='keep';
 if(el.dataset.recheckUpload){const overrides={...(pendingSource.overrides||{})};for(const input of small.querySelectorAll('[data-match-row]')){overrides[input.dataset.matchRow]={...overrides[input.dataset.matchRow],targetId:input.value};}for(const input of small.querySelectorAll('[data-correct-vin]'))overrides[input.dataset.correctVin]={...overrides[input.dataset.correctVin],vin:input.value};el.disabled=true;try{pendingSource=await previewUpload({uploadId:pendingSource.id,overrides});await refresh();sourceReviewModal();}finally{el.disabled=false;}}
 if(el.dataset.sort){if(sortKey===el.dataset.sort)sortDirection=sortDirection==='asc'?'desc':'asc';else{sortKey=el.dataset.sort;sortDirection='asc';}index=0;render();}
 if(el.dataset.duplicates)duplicatesModal(el.dataset.duplicates);
 if(el.dataset.duplicateField){nav('inventory');duplicateField=el.dataset.duplicateField;duplicateValue=el.dataset.duplicateValue;small.close();render();}
 if(el.dataset.clearDuplicates){duplicateField='';duplicateValue='';index=0;render();}
 if(el.dataset.withoutDriver){nav('inventory');driverFilter='unassigned';render();}
 if(el.dataset.section)sectionModal(el.dataset.section);
 if(el.dataset.driver)driverModal(el.dataset.driver);
 if(el.dataset.resolve)resolveModal(el.dataset.resolve);
 if(el.dataset.merge)mergeModal(el.dataset.merge);
 if(el.dataset.addEvidence)showSmall('Add source evidence',`<form id="evidence-form" class="stack"><label>Source name<input name="sourceName" required></label><label>Page / row / document reference<input name="locator"></label><label>Evidence note<textarea name="note" required minlength="3" rows="4"></textarea></label><div class="error" role="alert"></div><button class="primary">Save evidence</button></form>`);
 if(el.id==='add-btn')openVehicle(null);if(el.id==='import-btn')nav('sources');
 if(el.id==='commit-import'){el.disabled=true;try{const r=await api('/api/import/commit','POST',importData);small.close();await refresh();toast(`${r.added} vehicles added; ${r.matched} existing records received evidence.`);}finally{el.disabled=false;}}
 }catch(e){toast(e.message);}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='driver-search'){driverSearch=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();$('#driver-search')?.focus();},180);}if(e.target.dataset.correctVin){$('#approve-upload').disabled=true;}if(e.target.id==='search'){search=e.target.value;index=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=e.target.selectionStart;render();$('#search')?.focus();try{$('#search')?.setSelectionRange(pos,pos);}catch{}},180);}});
document.addEventListener('change',e=>{if(e.target.id==='upload-source'){const c=data.sourceTypes[e.target.value];$('#upload-file-label').innerHTML=esc(c.label)+'<input name="file" type="file" accept="'+c.accept+'" required>'; }if(e.target.dataset.matchRow){$('#approve-upload').disabled=true;}if(e.target.id==='driver-check-filter'){driverArea='';driverCheckFilter=e.target.value;render();}if(e.target.id==='section-filter'){sectionFilter=e.target.value;index=0;render();}if(e.target.id==='ownership-filter'){ownershipFilter=e.target.value;index=0;render();}if(e.target.id==='driver-filter'){driverFilter=e.target.value;index=0;render();}if(e.target.id==='filter'){filter=e.target.value;index=0;render();}if(e.target.id==='state-filter'){stateFilter=e.target.value;index=0;render();}if(e.target.closest('#import-form')){importData=null;$('#import-preview').innerHTML='';}});
document.addEventListener('submit',async e=>{if(e.target.getAttribute('action')==='/auth/logout')return;e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),button=f.querySelector('button[type="submit"],button.primary');if(button)button.disabled=true;const err=f.querySelector('.error');if(err)err.textContent='';try{
 if(f.id==='disposal-form'){const old=getV(f.dataset.id),action=b.operationalState==='Disposed'?'Disposed':'Restored';await api('/api/vehicles/'+old.id,'PUT',{version:Number(f.dataset.version),operationalState:b.operationalState,notes:(old.notes?old.notes+'\n':'')+action+' '+new Date().toISOString().slice(0,10)+': '+b.note.trim(),note:action+': '+b.note.trim()});small.close();index=0;await refresh();toast(action==='Disposed'?'Vehicle moved to Disposed vehicles.':'Vehicle restored to the current register.');}
 if(f.id==='new-driver-form'){await api('/api/driver-register','POST',b);small.close();await refresh();toast('Driver added.');}
 if(f.id==='source-upload-form'){const file=f.querySelector('[name=file]').files[0];$('#upload-progress').textContent='Reading the report and checking existing records…';const base64=await fileBase64(file);pendingSource=await previewUpload({sourceId:b.sourceId,filename:file.name,base64});await refresh();sourceReviewModal();}
 if(f.id==='source-review-form'){const decisions=Object.fromEntries(Object.entries(b).filter(([k])=>k!=='confirmed'));const r=await api('/api/source-upload/commit','POST',{uploadId:pendingSource.id,decisions,confirmed:b.confirmed==='on'});small.close();await refresh();toast(`Source saved: ${r.driversAdded} drivers added, ${r.vehiclesAdded} vehicles added, ${r.changed} approved updates, ${r.autoLinked||0} automatic driver links.`);}
 if(f.id==='section-form'){await api('/api/vehicles/'+f.dataset.id+'/section','POST',{section:b.section,version:Number(f.dataset.version)});small.close();await refresh();if(drawer.open)openVehicle(selected,tab);toast('CCS section saved.');}
 if(f.id==='driver-form'){await api('/api/vehicles/'+f.dataset.id+'/driver','POST',{driver:b.driver,driverId:b.driverId,version:Number(f.dataset.version)});small.close();await refresh();if(drawer.open)openVehicle(selected,tab);toast(b.driver.trim()?'Driver assignment saved.':'Driver assignment removed.');}
 if(f.id==='vehicle-form'){const old=selected?getV(selected):null;await api(selected?'/api/vehicles/'+selected:'/api/vehicles',selected?'PUT':'POST',{...b,...(old?{version:old.version}:{})});drawer.close();await refresh();toast('Vehicle saved.');}
 if(f.id==='verify-form'){await api('/api/vehicles/'+selected+'/verify','POST',{version:getV(selected).version,reviewer:b.reviewer,note:b.note,checks:Object.fromEntries(Object.keys(checks).map(k=>[k,b[k]==='on']))});await refresh();openVehicle(selected,'verify');toast('Verification progress saved.');}
 if(f.id==='resolve-form'){await api('/api/issues/'+f.dataset.id,'PUT',{status:'Resolved',note:b.note});small.close();await refresh();if(drawer.open)openVehicle(selected,tab);toast('Review item resolved.');}
 if(f.id==='merge-form'){const target=getV(b.targetId);await api('/api/vehicles/'+f.dataset.id+'/merge','POST',{...b,version:getV(f.dataset.id).version,targetVersion:target.version});small.close();await refresh();openVehicle(target.id,'evidence');toast('Records reconciled. Evidence and history retained.');}
 if(f.id==='evidence-form'){await api('/api/evidence','POST',{...b,vehicleId:selected});small.close();await refresh();openVehicle(selected,'evidence');toast('Evidence added.');}
 if(f.id==='document-form'){const file=f.querySelector('[name=file]').files[0];if(file.size>5*1024*1024)throw Error('Choose a file no larger than 5 MB.');const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});await api('/api/documents','POST',{vehicleId:b.vehicleId,filename:file.name,category:b.category,base64});await refresh();toast('Document uploaded.');}
 if(f.id==='import-form'){const file=f.querySelector('[name=file]').files[0];if(file.size>3*1024*1024)throw Error('CSV must be under 3 MB.');const csv=await file.text();const r=await api('/api/import/preview','POST',{csv});importData={csv,sourceName:b.sourceName,hash:r.hash};const errors=r.rows.filter(x=>x.error);$('#import-preview').innerHTML=`<h3 class="top-space">Preview: ${r.rows.length} rows</h3><p>${r.rows.filter(x=>x.action==='Create vehicle').length} new vehicles · ${r.rows.filter(x=>x.action==='Add evidence').length} existing matches · ${errors.length} errors</p><div class="table-wrap"><table><thead><tr><th>Row</th><th>VIN</th><th>Result</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${x.row}</td><td class="mono">${esc(x.vin)}</td><td>${esc(x.error||x.action)}</td></tr>`).join('')}</tbody></table></div><div class="form-footer"><button id="commit-import" class="primary" ${errors.length||!r.rows.length?'disabled':''}>Confirm import</button></div>`;}
 }catch(error){if(err)err.textContent=error.message;else toast(error.message);if(f.id==='source-upload-form'&&$('#upload-progress'))$('#upload-progress').textContent='';}finally{if(button)button.disabled=false;}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(navs.some(n=>n[0]===p)&&p!==page){page=p;index=0;render();}});
if(navs.some(n=>n[0]===location.hash.slice(1)))page=location.hash.slice(1);
refresh().catch(e=>content.innerHTML=`<div class="notice amber">Could not load the database: ${esc(e.message)}. Make sure the Node.js server is running, then refresh.</div>`);
